INSERT INTO Language_en_US (Tag, Text) VALUES
('TXT_KEY_SPECIALUNIT_AIRBASE', 'Airbase-based');

INSERT INTO Language_en_US (Tag, Text)
VALUES
-- EARLY MONOPLANE
('TXT_KEY_UNIT_EARLYMONOPLAN','Monoplane (Carrier)'),
('TXT_KEY_UNIT_HELP_EARLYMONOPLAN','An air unit designed to intercept incoming enemy aircraft and seize air superiority. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR]'),
('TXT_KEY_UNIT_EARLYMONOPLAN_STRATEGY','Monoplanes can be stationed in any city you own or based on an aircraft carrier. They can rebase from city to city (or carrier) and perform “missions” within range. Use fighters to engage enemy aircraft and ground units, scout enemy positions, and defend against enemy air attacks. See the Air Unit rules for details.'),
('TXT_KEY_EARLYMONOPLAN_TEXT','The interwar period (1919–1938) saw rapid progress in aviation. Aircraft design improved dramatically, evolving from 80-mph biplanes to streamlined racing aircraft exceeding 200 mph. Through the 1920s, advances allowed aircraft to fly farther, carry heavier loads, and become far more reliable. Most designs kept two synchronized machine guns ahead of the pilot, but armament gradually moved into the wings, outside the propeller arc. Rotary engines—so popular in WWI—quickly vanished as their rotational forces limited power; they were replaced mainly by fixed radials, while major advances in inline engines produced several excellent powerplants.[NEWLINE]With tight defense budgets, air forces were conservative about procurement and pilots still favored biplanes for their agility, keeping them in service well past their competitive prime. Designs such as the Gloster Gladiator, Fiat CR.42, and Polikarpov I-15 were common even in the late 1930s, and many served into 1942.[NEWLINE]Among the most groundbreaking fighters of this era was the PZL P.11, developed by engineer Zygmunt Puławski for Warsaw-based manufacturer PZL. First flown in 1934, its all-metal structure, metal skin, and high-mounted gull wing embodied features that briefly made it widely regarded as the most advanced fighter in the world.[NEWLINE]A total of 325 of these early monoplane fighters were built, achieving considerable export success.'),
-- P-80 Shooting Star
('TXT_KEY_UNIT_EARLYJET','P-80 Shooting Star (Airbase)'),
('TXT_KEY_UNIT_HELP_EARLYJET','An air unit designed to intercept incoming enemy aircraft and seize air superiority. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]Comes with 2 units when you complete the world wonder: The Pentagon.[ENDCOLOR][COLOR_NEGATIVE_TEXT] Cannot be produced by other means.[ENDCOLOR] [COLOR_POSITIVE_TEXT]Also starts with 4 bonus promotions:[ENDCOLOR][NEWLINE][COLOR_YELLOW][NEWLINE][ICON_BULLET] Air Supremacy II[NEWLINE][ICON_BULLET] Air Repair[NEWLINE][ICON_BULLET] Range[NEWLINE][ICON_BULLET] Shooting Star[ENDCOLOR][NEWLINE]'),
('TXT_KEY_UNIT_EARLYJET_STRATEGY','A civilization that builds the Pentagon world wonder receives two free P-80 Shooting Stars. They cannot be obtained otherwise. Though they begin with no XP, they come with strong baseline promotions. P-80s are stationed only in your cities and cannot embark on carriers. They rebase city-to-city and perform “missions” within range. Use them to attack enemy aircraft and ground units, scout, and defend against air strikes. See the Air Unit rules for details.'),
('TXT_KEY_EARLYJET_TEXT','The P-80 Shooting Star was the first jet fighter operated by the US Army Air Forces (USAAF). Designed and built by Lockheed in 1943, the production model flew a mere 143 days after the program began; two pre-production aircraft saw very limited service in Italy just before WWII ended. With straight wings, the type later served extensively in Korea with the USAF as the F-80.'),
-- JET FIGHTER (supersonic)
('TXT_KEY_UNIT_JET27','Jet Fighter (Carrier)'),
('TXT_KEY_UNIT_HELP_JET27','An air unit designed to intercept incoming enemy aircraft and seize air superiority. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR]'),
('TXT_KEY_UNIT_JET27_STRATEGY','Jet Fighters are powerful air units. They can be based in your cities or on aircraft carriers. They rebase between bases and perform “missions” within range. Use them to attack enemy aircraft and ground units, scout enemy locations, and defend against air attacks. Jets are especially effective against enemy helicopters. They also have “Aerial Recon,” revealing everything within 6 tiles of their base at the start of your turn. See the Air Unit rules for details.'),
('TXT_KEY_JET27_TEXT','The carrier-borne jet fighter concept at the end of the Cold War stemmed from the US Navy’s push for a single platform to handle both fleet air defense and strike missions. The F/A-18, a navalized evolution of the YF-17, replaced the A-7 and parts of the F-14’s role, executing the combined “F(ighter)/A(ttack)” task set repeatedly from the deck. It later evolved into the enlarged, re-engined, and re-avionics’d Super Hornet, becoming the backbone of carrier air wings.[NEWLINE][NEWLINE]The great advantage of a carrier fighter—projecting national power from a “mobile air base”—comes with harsh engineering and operational constraints. Traps require snagging the arresting wire and stopping within a few hundred meters (pilots maintain full throttle through touchdown as a standard “bolter-catch” procedure against cable failure), imposing severe cumulative fatigue on gear and airframe. Salt-laden maritime environments accelerate corrosion in electronics, wiring, and structure, demanding extensive anti-corrosion coatings, materials, and drainage/venting design. Tight deck/hangar space forces folding wings and low overall height, while payload, fuel, and serviceability must constantly be traded.[NEWLINE][NEWLINE]Operationally, carrier air wings cycle fleet air defense, strike, CAS, anti-ship/SEAD/DEAD in tightly scheduled “launch-recover” windows, with rearm/refuel/de-icing/corrosion checks and wiring inspections meshed across org- and intermediate-level maintenance. When deployed, wind over deck, deck clearance states, and the launch/recovery windows govern mission timing, while “bring-back weight limits” (fuel/ordnance allowed at trap) directly constrain planning. Carrier-capable jets must meet CATOBAR or STOBAR requirements in thrust, structural stiffness, and landing gear durability, narrowing MTOW, range, and load choices compared to land-based peers. Even so, multirole carrier fighters remain the “flexible blade” of the carrier air wing—combining air superiority and littoral/sea strike in one squadron, enabling distant deterrence and rapid response.'),
-- MiG-29
('TXT_KEY_UNIT_MIG29','MiG-29K (Multirole)'),
('TXT_KEY_UNIT_HELP_MIG29','An air unit designed to intercept incoming enemy aircraft and seize air superiority. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE]Like the Zero, gains combat bonuses versus enemy fighters and does not require Oil. [NEWLINE][NEWLINE]Only civilizations following the [ICON_IDEOLOGY_AUTOCRACY][COLOR_MAGENTA]Autocracy[ENDCOLOR] ideology may produce it, and the [COLOR_MAGENTA]Air Supremacy[ENDCOLOR] tenet must be adopted.'),
('TXT_KEY_UNIT_MIG29_STRATEGY','The MiG-29 is producible only under the Autocracy ideology with the Air Supremacy tenet unlocked. It remains a potent air unit that never truly goes obsolete. Aside from notable combat bonuses versus other fighters and not requiring [COLOR_POSITIVE_TEXT]Oil[ENDCOLOR], it functions like a standard jet. It can be based in your cities or on carriers, can rebase between city and carrier, and perform missions within 9 tiles. See the Air Unit rules for details.'),
('TXT_KEY_MIG29_TEXT','The MiG-29K is the carrier variant of the Soviet MiG-29 air-superiority fighter. Initiated in the late 1980s as the Soviet Naval Aviation sought new carriers (Kiev/Kuznetsov classes), mass deployment was derailed by the USSR’s collapse. The program revived in the 2000s with India’s carrier recapitalization (INS Vikramaditya and Vikrant), and Russia adopted it in limited numbers. The MiG-29K integrates RD-33MK engines, maritime-hardened avionics, anti-ship/strike weapons, folding wings, reinforced arresting gear, and corrosion protection—comprehensive adaptations for deck operations.[NEWLINE][NEWLINE]Carrier ops are demanding in design, maintenance, and tactics. Under **STOBAR** (ski-jump launch, arrested recovery), lack of catapults limits fuel/weapons on takeoff to meet thrust-to-weight and end-of-ramp speed requirements, reducing range and load options. Trapping on a short deck imposes high load impacts, requiring heavy reinforcement of gear and airframe—adding empty weight and maintenance burden. Salt environment raises corrosion and malfunction risks in electronics, wiring, and hydraulics; hangar/deck space constraints limit concurrent maintenance and sortie generation. The wing’s “cyclic operations” make wind and deck state the first constraint on mission plans.[NEWLINE][NEWLINE]To mitigate this, the MiG-29K adds large flaps and leading-edge devices, refined FBW laws for approach stability at various AoA/azimuth, radar modes favoring sea/ground mapping and GMTI, and integration of anti-ship missiles. Even so, fatigue accumulation, salt corrosion, and tight spares/maintenance cycles govern availability. Ultimately, performance is bounded by the carrier’s launch/recovery system (STOBAR/CATOBAR), deck maintenance infrastructure, and integration with the fleet’s navigation/AEW/tanker network.'),
-- ADVANCED FIGHTER (Stealth Jet)
('TXT_KEY_UNIT_ADVJET','Advanced Stealth Jet (Carrier)'),
('TXT_KEY_UNIT_HELP_ADVJET','A very powerful air unit designed to intercept incoming enemy aircraft and seize air superiority. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]Can be based on aircraft carriers.[ENDCOLOR]'),
('TXT_KEY_UNIT_ADVJET_STRATEGY','Advanced stealth jets are extremely capable air units. They can be based in your cities or on carriers, rebase between them, and perform “missions” within range. Use them to attack enemy aircraft and ground units, scout, and defend against air threats. They are especially effective versus helicopters and have “Aerial Recon,” revealing everything within 6 tiles of their base at turn start. See the Air Unit rules for details.'),
('TXT_KEY_ADVJET_TEXT','The idea of “hiding” combat aircraft dates back to the dawn of aviation, but the F-22 Raptor at the end of the Cold War proved the performance of true stealth. However, the Raptor was optimized for Air Force air superiority and lacked carrier suitability; combined with high acquisition/sustainment costs and export restrictions, it remained limited in numbers.[NEWLINE][NEWLINE]After the Cold War, the US sought a “multirole stealth fighter” to replace aging F-16s, F/A-18s, and AV-8Bs with a common family across Air Force, Navy, and Marine Corps to reduce costs. The Marines required STOVL, the Navy needed CATOBAR carrier operations, and the Air Force emphasized long-range strike and sensor fusion. To reconcile these divergent needs under one platform family, the Joint Strike Fighter (JSF) program began in the 1990s; in 2001 the X-35 was selected, leading to the F-35 Lightning II.[NEWLINE][NEWLINE]The F-35 combines low-observable shaping and internal bays with AESA radar, EO/DAS, IRST, EW systems, and link-based data fusion to “see first—shoot first—leave first.” It can switch between a low-observable internal-weapons configuration and an external-store “Beast Mode,” and its sustainment/software architecture emphasizes high sortie rates. [NEWLINE][NEWLINE]In short, the F-35 was designed not to replace the Raptor’s absolute air-superiority niche, but to unify land/sea/expeditionary forces with a multirole stealth platform. Its three variants—A (Air Force), B (STOVL), and C (Carrier)—deliver mission-tailored capabilities, reflecting the adage: “The Raptor opens the door; the Lightning goes through it to strike.”'),
-- Light BOMBER
('TXT_KEY_UNIT_LIGHTBOMBER','Light Bomber (Carrier)'),
('TXT_KEY_UNIT_HELP_LIGHTBOMBER','An air unit that can bomb enemy units and cities. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]Can be based on aircraft carriers.[ENDCOLOR]'),
('TXT_KEY_UNIT_LIGHTBOMBER_STRATEGY','Light bombers are effective versus cities and ground targets, less so versus naval targets, and very vulnerable to enemy aircraft. They can be based in your cities or on carriers, rebase between bases, and perform missions within range. Use them to attack enemy units and cities. If possible, send monoplanes or fighters first to “consume” enemy interception for the turn. See the Air Unit rules for details.'),
('TXT_KEY_LIGHTBOMBER_TEXT','From the end of WWI (1918) to the outbreak of WWII (1939), bombers evolved rapidly from slow wooden biplanes to sleek all-metal monoplanes. Metal construction, variable-pitch propellers, and improved aerodynamics gave rise to the concept of the “survive by speed” light bomber. Britain’s Bristol Blenheim and Fairey Battle, America’s Douglas A-20 Havoc/Boston, and Japan’s Ki-51, among others, were designed to strike quickly across the front with modest bombloads and high cruise speeds.[NEWLINE][NEWLINE]But once war began in earnest, light bombers’ thin armor, limited defensive guns, and small bombloads proved fatal weaknesses. In 1940 France, low-level daylight penetration by the Fairey Battle suffered heavy losses to fighters and flak, prompting a rapid shift to medium/high-altitude bombing and stronger escort doctrines. Many light bombers transitioned to specialized roles—night attack, reconnaissance, CAS, torpedo/anti-ship—thereafter.'),
-- STRATEGIC BOMBER
('TXT_KEY_UNIT_STRBOMB','Strategic Bomber (Airbase)'),
('TXT_KEY_UNIT_HELP_STRBOMB','A long-range air unit capable of delivering powerful strikes on enemy units and cities. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR]'),
('TXT_KEY_UNIT_STRBOMB_STRATEGY','Strategic bombers are effective against cities and land targets, less so against naval targets, and very vulnerable to enemy aircraft. They are based in your cities and cannot embark on carriers. They rebase between cities and perform missions within range. Use them to attack enemy units and cities. If possible, send fighters or jets first to “consume” enemy interception for the turn. See the Air Unit rules for details.'),
('TXT_KEY_STRBOMB_TEXT','Strategic bombers are medium- to long-range penetration aircraft designed to drop large quantities of air-to-ground weapons on distant targets to degrade the enemy’s capacity to wage war. Unlike tactical bombers, interdiction aircraft, fighter-bombers, and attack aircraft—which strike enemy combatants and equipment during air interdiction—strategic bombers fly deep into enemy territory to hit strategic targets (infrastructure, logistics, military installations, factories, and cities). They can also be used tactically.[NEWLINE]The first strategic efforts appeared in WWI, when Russia employed the Sikorsky Ilya Muromets—the first heavy four-engine aircraft—and Germany used Zeppelins and long-range multi-engine Gotha bombers.[NEWLINE][NEWLINE]By the late 1930s, many believed strategic “terror” bombing of cities would quickly inflict enormous losses, breaking a war within days or weeks. In practice, those theories outpaced what most air forces could actually field.[NEWLINE]The RAF only began developing four-engine long-range bombers in the late 1930s. The US Army Air Corps (becoming the USAAF in 1941) struggled under tight budgets but secured the B-17, which proved essential; the equally important B-24 first flew in 1939. These aircraft formed the bulk of the US bomber force enabling daylight raids over Nazi Germany from 1943–45.[NEWLINE][NEWLINE]During the Cold War, the US/UK on one side and the USSR on the other maintained alert strategic bomber fleets as part of MAD deterrence. Most strategic bombers were designed to carry nuclear weapons; for a time, some B-52 squadrons remained aloft 24/7 orbiting near fail-safe points close to Soviet airspace.[NEWLINE][NEWLINE]Nomenclature by “light/medium/heavy” has varied with technology and doctrine. The B-29 set a late-WWII benchmark for size/range/payload; with aerial refueling (which also extended the reach of medium bombers, fighter-bombers, and attack jets), intercontinental-range strategic bombing became feasible. In the 1950s, SAC revived the term “light bomber” to differentiate the Boeing B-47 Stratojet within wings otherwise hosting the larger B-52 Stratofortress; older B-29/B-50s were even redesignated “light” at times. Semantics aside, B-47s and B-52s dwarfed WWII mediums in size and performance. Other aircraft—US FB-111, Douglas A-3 Skywarrior, France’s Dassault Mirage IV—carried under 20,000 lb (9,100 kg) of ordnance and, relative to strategic bombers, fit “medium” categories. France later replaced the Mirage IV with the much smaller single-engine Mirage 2000N for nuclear strike—another example of evolving technology and doctrine.'),
-- B-52
('TXT_KEY_UNIT_B52','B-52 (Airbase)'),
('TXT_KEY_UNIT_HELP_B52','A long-range air unit that rains death on enemy units and cities. Has a chance to evade interception and deals extra damage to cities compared to Strategic Bombers. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE]Only civilizations following [ICON_IDEOLOGY_FREEDOM][COLOR_MAGENTA]Freedom[ENDCOLOR] may produce it, and the [COLOR_MAGENTA]Their Finest Hour[ENDCOLOR] tenet must be adopted.'),
('TXT_KEY_UNIT_B52_STRATEGY','The B-52 can be produced only under the Freedom ideology with Their Finest Hour unlocked. Similar to a bomber but harder for enemy AA and fighters to target. It also gains a bonus against cities. Unlike a Strategic Bomber, its range is 14 (+1). See the Air Unit rules for details.'),
('TXT_KEY_B52_TEXT','Also known as the Stratofortress, the B-52 is a US long-range heavy bomber designed by Boeing in 1948, first flown in 1952, and delivered to the military in 1955. It proved adaptable to many roles throughout the Cold War, and dozens remained in service into the 21st century. With eight jet engines beneath its wings, it can reach about Mach 0.9 at 55,000 feet and Mach 0.5 at a few hundred feet AGL. Its massive airframe—nicknamed the “Big Ugly Fat Fellow” (BUFF)—accommodates sophisticated navigation, weapons control, and electronic countermeasures. For years, it also served as the “mothership” for air-launched experimental aircraft like the X-15 and X-43.'),
-- JET BOMBER
('TXT_KEY_UNIT_ULTJETBOMB','Jet Bomber (Airbase)'),
('TXT_KEY_UNIT_HELP_ULTJETBOMB','A long-range air unit that delivers heavier strikes on enemy units and cities.[NEWLINE][COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR]'),
('TXT_KEY_UNIT_ULTJETBOMB_STRATEGY','Jet bombers are effective against cities and ground targets, less so at sea, and very vulnerable to enemy aircraft. They are based in your cities and cannot embark on carriers. They rebase between bases and perform missions within range. Use them to attack enemy units and cities. If possible, send jet or stealth fighters first to “consume” enemy interception for the turn. See the Air Unit rules for details.'),
('TXT_KEY_ULTJETBOMB_TEXT','Since the end of the Cold War, long-range bombing has shifted from low-altitude penetration to stand-off strike. With the spread of integrated air defenses (IADS) and precision-guided munitions, jet bombers have evolved into platforms mass-employing long-range weapons—cruise missiles, glide bombs, and hypersonic systems—often under cover of stealth and electronic warfare. The USAF is life-extending the B-52 with re-engining and avionics modernization as a long-range cruise-missile “truck,” while the B-1B focuses on conventional strike. Russia has upgraded the Tu-160M and Tu-22M3M for range and avionics.[NEWLINE][NEWLINE]China has likewise modernized its H-6K/H-6N series at scale, carrying long-range land-attack and anti-ship weapons to enhance A2/AD reach—engaging littoral and maritime targets from beyond [ICON_RANGE_STRENGTH] enemy air-defense range. With a next-generation stealth strategic bomber announced (details undisclosed), future roles likely center on low-observable design, long-range armament, and network-centric “sense-decide-strike” kill chains.');

INSERT INTO Language_en_US (Tag, Text) VALUES
-- Shooting Star Promotion & Pentagon Wonder Help
('TXT_KEY_PROMOTION_JET_DOM','Shooting Star'),
('TXT_KEY_PEDIA_PROMOTION_JET_DOM','Shooting Star'),
('TXT_KEY_PROMOTION_JET_DOM_HELP','[ICON_RANGE_STRENGTH] Ranged Combat [COLOR_POSITIVE_TEXT]+10%[ENDCOLOR][NEWLINE]vs. Fighter units: [ICON_STRENGTH] Combat Bonus [COLOR_POSITIVE_TEXT]+10%[ENDCOLOR][NEWLINE]Damage taken from Interception [COLOR_POSITIVE_TEXT]-10%[ENDCOLOR]'),
-- Carrier airship promotion
('TXT_KEY_PROMOTION_CARRIER_OPS','Carrier Operations'),
('TXT_KEY_PROMOTION_CARRIER_OPS_HELP','vs. Naval and Land units: [ICON_STRENGTH] Combat Bonus [COLOR_POSITIVE_TEXT]+5%[ENDCOLOR][NEWLINE]vs. Cities: [ICON_STRENGTH] Combat [COLOR_POSITIVE_TEXT]+5%[ENDCOLOR]'),
-- Airbase garrison promotion
('TXT_KEY_PROMOTION_AIRBASE_OPS','Airbase Garrison'),
('TXT_KEY_PROMOTION_AIRBASE_OPS_HELP','vs. Fighter units: [ICON_STRENGTH] Combat Bonus [COLOR_POSITIVE_TEXT]+5%[ENDCOLOR][NEWLINE]Damage taken from Interception [COLOR_POSITIVE_TEXT]-5%[ENDCOLOR]');

------------------------------------------------------------
-- Original Remaining
------------------------------------------------------------
UPDATE Language_en_US
SET Text = 'Triplane (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_TRIPLANE';

UPDATE Language_en_US
SET Text = 'Piston Fighter (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_FIGHTER';

UPDATE Language_en_US
SET Text = 'The piston fighter is a moderately powerful air unit. It is stationed in cities you own and cannot be based on carriers. It can rebase between cities and perform “operations” within range. Use fighters to attack enemy aircraft and ground forces, scout enemy positions, and defend against enemy air raids. Fighters are especially effective against enemy helicopters. See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_FIGHTER_STRATEGY';

UPDATE Language_en_US
SET Text = 'Biplane Bomber (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_WWI_BOMBER';

UPDATE Language_en_US
SET Text = 'The biplane bomber is an early air unit. It is effective versus land targets, less so at sea, and very vulnerable to enemy aircraft. It is stationed in your cities and cannot be based on carriers. It rebases between cities and performs missions within range. Use it to attack enemy units and cities. If possible, in the same turn first “consume” enemy interception with triplanes or monoplanes. See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_WWI_BOMBER_STRATEGY';

UPDATE Language_en_US
SET Text = 'Heavy Bomber (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_BOMBER';

UPDATE Language_en_US
SET Text = 'The heavy bomber is an air unit. It is effective versus land targets, ineffective at sea, and fairly vulnerable to enemy aircraft. Heavy bombers are stationed in your cities and cannot be based on carriers. They can rebase between cities and perform missions within range. Use them to attack enemy units and cities. If possible, send fighters first to “consume” enemy AA fire. See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_BOMBER_HELP';

UPDATE Language_en_US
SET Text = 'The heavy bomber is an air unit. It is effective versus land targets, ineffective at sea, and fairly vulnerable to enemy aircraft. Heavy bombers are stationed in your cities and cannot be based on carriers. They can rebase between cities and perform missions within range. Use them to attack enemy units and cities. If possible, send fighters first to “consume” enemy AA fire. See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_BOMBER_STRATEGY';

UPDATE Language_en_US
SET Text = 'A long-range air unit that rains death on enemy units and cities. Has some chance to evade interception and deals greater damage—and has greater range—against cities than a standard bomber. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR][NEWLINE][NEWLINE]Only civilizations following [ICON_IDEOLOGY_FREEDOM][COLOR_MAGENTA]Freedom[ENDCOLOR] may produce it, and the [COLOR_MAGENTA]Their Finest Hour[ENDCOLOR] tenet must be adopted.'
WHERE Tag = 'TXT_KEY_UNIT_AMERICAN_B17_HELP';

UPDATE Language_en_US
SET Text = 'The B-17 is the unique unit for the Freedom ideology. You must adopt the [COLOR_MAGENTA]Their Finest Hour[ENDCOLOR] tenet. Similar to a standard heavy bomber, but harder for enemy AA and fighters to target. Also gains additional bonuses when attacking cities. Unlike the base bomber, its range is 13 (+1). See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_AMERICAN_B17_STRATEGY';

UPDATE Language_en_US
SET Text = 'A6M Zero (Multirole)'
WHERE Tag = 'TXT_KEY_UNIT_JAPANESE_ZERO';

UPDATE Language_en_US
SET Text = 'The Zero is the unique unit of the Autocracy ideology. You must adopt the [COLOR_MAGENTA]Air Supremacy[ENDCOLOR] tenet. It is a mid-power air unit similar to standard fighters, but receives large combat bonuses versus other fighters and [COLOR_POSITIVE_TEXT]does not require Oil[ENDCOLOR]. It can be based in any city you own and also operate from carriers. It can rebase between city and carrier and perform missions within 8 tiles. See the Air Unit rules for details.'
WHERE Tag = 'TXT_KEY_UNIT_JAPANESE_ZERO_STRATEGY';

UPDATE Language_en_US
SET Text = 'Designed to intercept incoming enemy aircraft and seize air superiority. Gains bonuses versus enemy fighters and [ICON_RES_OIL] does not require Oil. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR] [NEWLINE][NEWLINE]Only civilizations following [ICON_IDEOLOGY_AUTOCRACY][COLOR_MAGENTA]Autocracy[ENDCOLOR] may produce it, and the [COLOR_MAGENTA]Air Supremacy[ENDCOLOR] tenet must be adopted.'
WHERE Tag = 'TXT_KEY_UNIT_JAPANESE_ZERO_HELP';

UPDATE Language_en_US
SET Text = 'Stealth Fighter (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_JET_FIGHTER';

UPDATE Language_en_US
SET Text = 'A stealth air-superiority fighter designed to dominate the skies and intercept incoming enemy aircraft. [COLOR_POSITIVE_TEXT]Does not consume Military Supply.[ENDCOLOR]'
WHERE Tag = 'TXT_KEY_UNIT_HELP_JET_FIGHTER';

UPDATE Language_en_US
SET Text = 'The F-22 Raptor is a stealth air-superiority fighter from the late-Cold-War ATF program, fielded after the YF-22 prototype competition. Entering USAF service in the mid-2000s, it combined low-observable shaping/coatings and internal bays with high-agility thrust-vectoring, the APG-77 AESA radar, and tightly integrated avionics/data fusion to realize the classic “see first—shoot first—leave first” air-superiority paradigm. Supercruise enabled energy-dominant tactics, while EW/passive-sensor integration and link-enabled situational awareness unlocked formation-level target sharing and multi-axis approaches.[NEWLINE][NEWLINE]Historically, the F-22 was optimized as an Air Force standalone air-superiority platform; carrierization proposals fell to technical and economic hurdles. Carrier suitability would have required arresting hook and heavy landing gear, structural reinforcement for trap loads, corrosion protection and sealing/venting for salt environments, folding wings, and more—driving weight growth, avionics/weapons compromises, and exploding costs. Divergent AF/USN operational concepts (sortie cycles vs. deck cycles) compounded the issue. As a result, the F-22 remains a land-based air-dominance asset.[NEWLINE][NEWLINE]In gameplay, stealth fighters excel at bomber escort and IADS penetration via interception evasion and BVR advantages, offsetting enemy numerical superiority with superior tactics. However, they are less suited to blue-water power projection; pairing with carrier fighters (F/A-18, MiG-29K, F-35, etc.) is ideal for maritime operations.'
WHERE Tag = 'TXT_KEY_CIVILOPEDIA_UNITS_MODERN_JETFIGHTER_TEXT';

UPDATE Language_en_US
SET Text = 'Stealth Bomber (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_STEALTH_BOMBER';

------------------------------------------------------------
-- Finest Hour policy text
------------------------------------------------------------
UPDATE Language_en_US
SET Text = '[COLOR_POSITIVE_TEXT]Their Finest Hour[ENDCOLOR]: All cities get +2 Air Unit Slots. Each Air Unit stationed in a city increases the City''s [ICON_STRENGTH] Defense by 3. Can build [COLOR_YELLOW]B17 Bombers[ENDCOLOR] and [COLOR_YELLOW]B-52 Bomber[ENDCOLOR].'
WHERE Tag = 'TXT_KEY_POLICY_THEIR_FINEST_HOUR_HELP';

------------------------------------------------------------
-- Militarism policy text (Air Supremacy)
------------------------------------------------------------
UPDATE Language_en_US
SET Text = '[COLOR_POSITIVE_TEXT]Air Supremacy[ENDCOLOR]: Receive a free Airport in every City. +25% [ICON_PRODUCTION] Production when building Aircraft. Can build [COLOR_YELLOW]Zeroes[ENDCOLOR] and [COLOR_YELLOW]MiG-29K[ENDCOLOR].'
WHERE Tag = 'TXT_KEY_POLICY_MILITARISM_HELP';

------------------------------------------------------------
-- Pentagon wonder help
------------------------------------------------------------
UPDATE Language_en_US
SET Text = 'Spawns 2 free [COLOR_YELLOW]P-80 Shooting Stars[ENDCOLOR]. +[COLOR_POSITIVE_TEXT]50%[ENDCOLOR] [ICON_PRODUCTION] when producing air units. Air units trained in this city gain [COLOR_POSITIVE_TEXT]20[ENDCOLOR] XP. [ICON_WAR] Global Military Supply +[COLOR_POSITIVE_TEXT]1[ENDCOLOR]; city Air Unit capacity +[COLOR_POSITIVE_TEXT]2[ENDCOLOR]. [NEWLINE][NEWLINE]Requires completion of the [COLOR_MAGENTA]Imperialism[ENDCOLOR] policy tree. This is a [COLOR_POSITIVE_TEXT]World Wonder[ENDCOLOR] (one globally).'
WHERE Tag = 'TXT_KEY_WONDER_PENTAGON_HELP';

