-- Compatibility Patch
---=========================================================================================================================
UPDATE Language_en_US
SET Text = 'Stealth UCAV Squadron (Multirole)'
WHERE Tag = 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2'
  AND EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_DRONE_FIGHTER_2');

INSERT INTO Language_en_US (Tag, Text)
SELECT 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2', 'Stealth UCAV Squadron (Carrier-capable)'
WHERE EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_DRONE_FIGHTER_2')
  AND NOT EXISTS (SELECT 1 FROM Language_en_US WHERE Tag = 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2');

UPDATE Language_en_US
SET Text = 'Sub-orbital Bomber (Airbase)'
WHERE Tag = 'TXT_KEY_UNIT_FW_SUBORBITAL_BOMBER'
  AND EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_SUBORBITAL_BOMBER');

INSERT INTO Language_en_US (Tag, Text)
SELECT 'TXT_KEY_UNIT_FW_SUBORBITAL_BOMBER', 'Sub-orbital Bomber (Airbase)'
WHERE EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_SUBORBITAL_BOMBER')
  AND NOT EXISTS (SELECT 1 FROM Language_en_US WHERE Tag = 'TXT_KEY_UNIT_FW_SUBORBITAL_BOMBER');
